import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';
// D.Gray-man 驱魔少年 MVU Zod Schema
export const Schema = z.object({
  身份模式: z.enum(["原作","取代","共存"]).prefault("原作"),
  当前模式: z.enum(["剧情","沙盒"]).prefault("剧情"),
  user: z.object({
    名称: z.string().prefault("{{user}}"),
    身份: z.string().prefault("驱魔师候补"),
    当前位置: z.string().prefault("黑色教团总部"),
  }).prefault({}),
  关系网: z.record(z.string(), z.object({
    好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    信任度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    关系: z.string().prefault("未接触"),
  })).prefault({ 亚连沃克: { 好感度: 50, 信任度: 40, 关系: "同僚" } }).describe("角色名"),
  剧情: z.object({
    当前篇章: z.string().prefault("序章"),
    当前卷: z.coerce.number().transform(v => _.clamp(v, 1, 30)).prefault(1),
    当前章节: z.string().prefault("第01章 终结之谷的悲歌与左手的觉醒"),
    当前事件: z.coerce.number().transform(v => _.clamp(v, 0, 10)).prefault(0),
    事件完成: z.record(z.string(), z.boolean()).prefault({}).describe("事件名"),
    模式: z.enum(["日常","推进"]).prefault("推进"),
    推进许可: z.boolean().prefault(false),
  }).prefault({}),
  隐秘资讯: z.object({
    第二驱魔师真相: z.boolean().prefault(false),
    第十四号真相: z.boolean().prefault(false),
    坎贝尔家族真相: z.boolean().prefault(false),
    圣洁之心线索: z.boolean().prefault(false),
    诺亚家族完整真相: z.boolean().prefault(false),
    千年伯爵真相: z.boolean().prefault(false),
    阿尔玛真相: z.boolean().prefault(false),
    独立圣洁存在: z.boolean().prefault(false),
  }).prefault({}),
  沙盒状态: z.object({
    当前时间: z.string().prefault("第1天·午前"),
    当前位置: z.string().prefault("黑色教团总部"),
    天气: z.string().prefault("晴"),
    时段: z.enum(["早晨","午前","午后","夕方","夜","深夜"]).prefault("午前"),
    时间推进次数: z.coerce.number().transform(v => _.clamp(v, 0, 9999)).prefault(0),
    关键事件触发记录: z.record(z.string(), z.boolean()).prefault({}).describe("事件名"),
  }).prefault({}),
  角色阶段: z.record(z.string(), z.object({
    好感度阶段: z.coerce.number().transform(v => _.clamp(v, 0, 4)).prefault(0),
    关系阶段: z.string().prefault("初识"),
  })).prefault({}).describe("角色名"),
});


$(() => {
  registerMvuSchema(Schema);
});

const SAND=['[DGM] 沙盒'];
const M={"0":"story","1":"story","2":"story","3":"sandbox","4":"sandbox","5":"sandbox"};
let cur=-1,init=false,iv=null;
async function update(idx){
  const m=M[idx.toString()];if(!m)return;
  const b=TavernHelper.getCurrentCharPrimaryLorebook();if(!b)return;
  try{
    const es=await TavernHelper.getLorebookEntries(b);if(!es)return;
    const mods=[];
    for(const e of es){
      const c=e.comment||'';
      if(SAND.some(n=>c.includes(n))&&e.enabled!==(m==='sandbox'))mods.push({uid:e.uid,enabled:m==='sandbox'});
    }
    if(mods.length){await TavernHelper.setLorebookEntries(b,mods);toastr.success(m==='story'?'剧情模式':'沙盒模式');}
  }catch(e){console.error(e);}
}
async function gsi(){try{const ms=await TavernHelper.getChatMessages(0,{include_swipe:true});return(ms&&ms[0])?(ms[0].swipe_id||0):-1;}catch(e){return -1;}}
async function mon(){try{const i=await gsi();if(i>=0&&i!==cur){if(init)toastr.info('开局已切换');cur=i;await update(i);}}catch(e){}}
async function load(){try{cur=await gsi();init=true;await update(cur);iv=setInterval(mon,500);TavernHelper.onMessageSwiped(()=>setTimeout(mon,200));}catch(e){console.error(e);}}
function unload(){if(iv)clearInterval(iv);}
load();

